  "factors": [
    {
      "name": "vol_reversal_depth",
      "expression": "TS_ARGMAX(TS_ZSCORE($volume, 10), 20) - TS_ARGMIN(TS_ZSCORE($close, 10), 20)",
      "explanation": "Measures the difference between the highest and lowest volume-weighted close ranks over two windows, exploring depth in reversal patterns."
    },
    {
