"Low-volatility stocks show mean-reversion in short-term returns during regime transitions, driven by temporary mispricing as market participants adjust to new conditions.",
  "factors": [
    {
      "name": "volatility_gap",
      "expression": "RANK(TS_QUANTILE($return, 60, 0.9) - TS_QUANTILE($return, 60, 0.1) / TS_MAD($return, 60))",
      "explanation": "Computes the gap between upper and lower quantiles of returns, normalized by volatility, then ranks it to find stocks with the most extreme price movements."
    },
    {
      "name": "residual_volume",
      "expression": "RANK(REGRESI($volume, $return, 60) - MEAN($volume))",
      "explanation": "Calculates the residual of volume regressed on returns, subtracts the mean, and ranks it to identify stocks where volume deviates from expected levels."
    },
    {
      "name": "asymmetry_weighted",
      "expression": "RANK((TS_PCTCHANGE($close, 30) > 0 ? TS_STD($return, 30) : 0) - (TS_PCTCHANGE($close, 30) < 0 ? TS_STD($return, 30) : 0))",
      "explanation": "Measures the asymmetric impact of price changes on return volatility, ranks the difference to highlight stocks with divergent behavior."
    },
    {
      "name": "cross_volatility",
      "expression": "RANK(TS_CORR($open, $volume, 60) * TS_VAR($return, 60))",
      "explanation": "Captures the relationship between open prices and volume, multiplied by return variance, to spot stocks where price activity correlates with volatility."
    },
    {
      "name": "depth_skew",
      "expression": "RANK(TS_ARGMAX($return, 20) - TS_ARGMIN($return, 20) / TS_MAD($return, 60))",
      "explanation": "Identifies the distance between the highest and lowest returns over 20 days, scaled by volatility, to detect stocks with extreme price swings."
    },
    {
      "name": "inverted_momentum",
      "expression": "RANK(1 - TS_ZSCORE($return, 20) * TS_ZSCORE($volume, 20))",
      "explanation": "Inverts the product of return and volume z-scores to find stocks where momentum and trading activity are out of sync."
    }
  ]
}

